class Solution {
  public long maxEarnings(int[][] meetings) {
    int n = meetings.length;
    int[][] sorted = meetings.clone();
    java.util.Arrays.sort(sorted, (a, b) -> Integer.compare(a[0], b[0]));
    java.util.PriorityQueue<long[]> pending =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    long NEG = Long.MIN_VALUE / 4, bestKey = NEG, answer = Long.MIN_VALUE;
    for (int[] m : sorted) {
      while (!pending.isEmpty() && pending.peek()[0] <= m[0])
        bestKey = Math.max(bestKey, pending.poll()[1]);
      long best = 0;
      if (bestKey > NEG) best = Math.max(0, bestKey + m[0]);
      long dp = m[2] + best;
      answer = Math.max(answer, dp);
      pending.add(new long[] {m[1], dp - m[1]});
    }
    return answer;
  }
}
